using UnityEngine;using UnityEngine.UI;
public class ARShowroomUI:MonoBehaviour{public ARPlacementManager placement;public Text status;int i;Color[] colors={new Color(.04f,.18f,.85f),new Color(.8f,.03f,.03f),new Color(.03f,.03f,.03f),new Color(.75f,.75f,.78f),new Color(.05f,.55f,.2f)};public void Color(){var c=placement.CurrentCar;if(c){i=(i+1)%colors.Length;c.GetComponent<CarController>().SetColor(colors[i]);}}public void Doors(){var c=placement.CurrentCar;if(c)c.GetComponent<CarController>().ToggleDoors();}public void Lights(){var c=placement.CurrentCar;if(c)c.GetComponent<CarController>().ToggleLights();}public void Engine(){var c=placement.CurrentCar;if(c)c.GetComponent<CarController>().ToggleEngine();}public void Info(){if(status)status.text="AR CAR SHOWROOM • Premium Sports Sedan • AWD • 420 HP • 250 km/h • 0–100 km/h: 4.2 s • 5 seats";}public void Reset(){placement.ResetCar();if(status)status.text="Move camera to scan a floor, then tap to place the car.";}}
